'use client';

import * as React from 'react';
import {createComponent} from '@lit/react';
import '@material/web/labs/gb/components/splitbutton/md-gb-split-button.js';
import {SplitButtonElement} from '@material/web/labs/gb/components/splitbutton/split-button-element.js';

/**
 * A Material Design component. Wraps <md-gb-split-button>.
 * Docs: https://material-web.dev/3.0/components/split-button/
 */
export const MdSplitButton = createComponent({
  react: React,
  tagName: 'md-gb-split-button',
  elementClass: SplitButtonElement,
});

export type MdSplitButtonProps = React.ComponentProps<typeof MdSplitButton>;
